        ["_User"] = "_Benutzer",
        ["A child declaration in angle brackets, such as <DeviceName>: it stands for any number of children of its type. A MandatoryPlaceholder needs at least one."] = "Eine Kinddeklaration in spitzen Klammern, etwa <DeviceName>, die für beliebig viele Kindknoten ihres Typs steht. Ein MandatoryPlaceholder braucht mindestens einen.",
        ["A companion specification or your own model as NodeSet2.xml, or drop the files here; required models are found in the NodeSet folders."] = "Eine Companion Specification oder dein eigenes Modell als NodeSet2.xml, oder zieh die Dateien hierher; benötigte Modelle werden in den NodeSet-Ordnern gesucht.",
        ["A Mandatory child of the type is missing."] = "Ein Kindelement, das der Typ als Mandatory deklariert, fehlt.",
