        ["Create"] = "Anlegen",
        ["Create an instance of a UA type and check it against the type."] = "Lege eine Instanz eines UA-Typs an und prüfe sie gegen den Typ.",
        ["Create an instance of a UA type with its Mandatory children and the Optional children you choose."] = "Eine Instanz eines UA-Typs anlegen, mit ihren Mandatory-Kindelementen und den Optional-Kindelementen, die du wählst.",
        ["Create elements for the checked parts, or for the selected node with what is below it; taking a part again updates it."] = "Elemente für die angehakten Teile anlegen oder für den ausgewählten Knoten mit allem darunter; wird ein Teil erneut übernommen, wird er aktualisiert.",
