        ["The server at {0} did not accept this computer's certificate. Its administrator has to trust it; it is in '{1}'."] = "Der Server unter {0} hat das Zertifikat dieses Computers nicht angenommen. Sein Administrator muss ihm vertrauen; es liegt in '{1}'.",
        ["Do it"] = "Ausführen",
