        ["Drop NodeSet files to import"] = "NodeSet-Dateien zum Importieren hier ablegen",
        ["Drop the changes"] = "Änderungen verwerfen",
        ["Drop the changes in the modeler?"] = "Die Änderungen im Modeler verwerfen?",
        ["Each file becomes AutomationML libraries by OPC 10000-83 Annex A, with the models it requires."] = "Aus jeder Datei werden AutomationML-Bibliotheken nach OPC 10000-83 Annex A, zusammen mit den Modellen, die sie benötigt.",
        ["Each OPC UA model imported into the document, with its version and publication date. An import turns a NodeSet into AutomationML libraries by Annex A: attribute types (ATL_), interface classes (ICL_), role classes (RCL_) and system unit classes (SUC_) per namespace, together with the models it requires. Select a namespace to see what it brings, what it builds on and which elements use its types; Documentation… writes all of it as one HTML page with diagrams."] = "Jedes OPC-UA-Modell, das ins Dokument importiert wurde, mit Version und Veröffentlichungsdatum. Ein Import macht aus einem NodeSet AutomationML-Bibliotheken nach Annex A: AttributeTypes (ATL_), InterfaceClasses (ICL_), RoleClasses (RCL_) und SystemUnitClasses (SUC_) je Namespace, zusammen mit den Modellen, die es benötigt. Wähle einen Namespace, um zu sehen, was er mitbringt, worauf er aufbaut und welche Elemente seine Typen verwenden; Dokumentation… schreibt all das als eine HTML-Seite mit Diagrammen.",
        ["Earlier conversions forgotten; the next import converts again."] = "Frühere Umwandlungen vergessen; der nächste Import wandelt erneut um.",
        ["Edit"] = "Bearbeiten",
        ["Edit a namespace of the document, start a new model, or open a NodeSet file. 'Apply to document' in the modeler imports the result."] = "Bearbeite einen Namespace des Dokuments, lege ein neues Modell an oder öffne eine NodeSet-Datei. 'Ins Dokument übernehmen' im Modeler importiert das Ergebnis.",
        ["Edit in the modeler"] = "Im Modeler bearbeiten",
        ["Edit the NodeSet of this namespace in the modeler."] = "Bearbeite das NodeSet dieses Namespaces im Modeler.",
        ["Edits NodeSets, not the document. Edit opens the NodeSet a namespace was imported from, New model starts an empty one, Open NodeSet file any other. The modeler's Apply to document imports the result like any NodeSet; its Save NodeSet writes the file. 'Modeler *' on the tab means changes neither applied nor saved; the plugin asks before it drops them."] = "Bearbeitet NodeSets, nicht das Dokument. 'Bearbeiten' öffnet das NodeSet, aus dem ein Namespace importiert wurde, 'Neues Modell' legt ein leeres an, 'NodeSet-Datei öffnen' öffnet jedes andere. 'Ins Dokument übernehmen' im Modeler importiert das Ergebnis wie jedes NodeSet; 'NodeSet speichern' dort schreibt die Datei. 'Modeler *' auf dem Reiter heißt: Die Änderungen sind weder übernommen noch gespeichert; das Plugin fragt, bevor es sie verwirft.",
        ["Element"] = "Element",
        ["Elements"] = "Elemente",
        ["Endpoint"] = "Endpunkt",
        ["Endpoint URL"] = "Endpunkt-URL",
        ["Endpoint URL, e.g. opc.tcp://host:4840. Enter connects; the list holds the servers used recently."] = "Endpunkt-URL, z. B. opc.tcp://host:4840. Enter verbindet; die Liste enthält die zuletzt verwendeten Server.",
        ["Enter a name for the instance."] = "Gib einen Namen für die Instanz ein.",
        ["Enter a namespace URI of your own, such as http://example.org/MyPlant/, and click New model."] = "Gib eine eigene Namespace-URI ein, etwa http://example.org/MyPlant/, und klicke auf 'Neues Modell'.",
        ["Enter a whole number from {0} to {1} as depth."] = "Gib als Tiefe eine ganze Zahl von {0} bis {1} ein.",
        ["Enter a whole number from {0} to {1} as diagram depth."] = "Gib als Diagrammtiefe eine ganze Zahl von {0} bis {1} ein.",
        ["Enter a whole number from {0} to {1} as node limit."] = "Gib als Höchstzahl der Knoten eine ganze Zahl von {0} bis {1} ein.",
        ["Enter a whole number from {0} to {1} as port."] = "Gib als Port eine ganze Zahl von {0} bis {1} ein.",
        ["Every Mandatory child of the type is created, the Optional children you tick, and for a placeholder the children you name."] = "Angelegt werden alle Mandatory-Kindelemente des Typs, die Optional-Kindelemente, die du anhakst, und bei einem Platzhalter die Kindelemente, die du benennst.",
        ["every {0} below {1}"] = "alle {0} unter {1}",
        ["Expand the address space down to your instance and tick its box. Right click it to choose how much below it to take."] = "Klappe den Adressraum bis zu deiner Instanz auf und hake sie an. Wähle per Rechtsklick darauf, wie viel darunter übernommen wird.",
        ["Export as OPC UA NodeSet"] = "Als OPC UA NodeSet exportieren",
        ["Export failed: {0}"] = "Export fehlgeschlagen: {0}",
        ["Export NodeSet…"] = "NodeSet exportieren…",
        ["Export SVG…"] = "SVG exportieren…",
        ["Export this document as an OPC UA NodeSet by the rules of the AutomationML/OPC Foundation working group (AML-UA-XSLT, successor of OPC 30040)."] = "Exportiere dieses Dokument als OPC UA NodeSet nach den Regeln der Arbeitsgruppe von AutomationML und OPC Foundation (AML-UA-XSLT, Nachfolger von OPC 30040).",
        ["Exported {0} node(s) to {1}."] = "{0} Knoten nach {1} exportiert.",
        ["Exporting …"] = "Wird exportiert …",
        ["Export…"] = "Exportieren…",
        ["Fetching from the OPC Foundation failed: {0}"] = "Abruf von der OPC Foundation fehlgeschlagen: {0}",
        ["The OPC Foundation does not publish {0}. A NodeSet folder or the UA Cloud Library may have it."] = "Die OPC Foundation veröffentlicht {0} nicht. Ein NodeSet-Ordner oder die UA Cloud Library hat es vielleicht.",
        ["Nothing could be fetched from the OPC Foundation."] = "Von der OPC Foundation ließ sich nichts abrufen.",
        ["Fetching the missing models from the OPC Foundation …"] = "Fehlende Modelle werden von der OPC Foundation abgerufen …",
        ["Filter types and instances by name; Enter draws the first"] = "Typen und Instanzen nach Namen filtern; Enter zeichnet den ersten Treffer",
        ["Finding"] = "Befund",
        ["Findings; Enter selects the element"] = "Befunde; Enter wählt das Element aus",
        ["Fit"] = "Einpassen",
        ["Fit the diagram into the view"] = "Diagramm in die Ansicht einpassen",
        ["Folder with NodeSet files"] = "Ordner mit NodeSet-Dateien",
        ["Folder with the NodeSets {0} requires"] = "Ordner mit den NodeSets, die {0} benötigt",
        ["Folders searched for NodeSets that an import requires. The UA base model and DI are built in."] = "Ordner, in denen nach NodeSets gesucht wird, die ein Import benötigt. Das UA-Basismodell und DI sind eingebaut.",
        ["Following {0} bound value(s) of {1}"] = "{0} gebundene Wert(e) von {1} werden live gehalten",
        ["; {0} bound to another server left out"] = "; {0} an einen anderen Server gebundene ausgelassen",
        ["; {0} not on this server (see log)"] = "; {0} nicht auf diesem Server (siehe Protokoll)",
        ["None of the {0} bound value(s) is on {1} (see log)."] = "Keiner der {0} gebundenen Wert(e) ist auf {1} (siehe Protokoll).",
        ["For the modeler or a file; an import takes the types, the objects come in through 'Take into document'."] = "Für den Modeler oder eine Datei; ein Import übernimmt nur die Typen, die Objekte kommen über 'Ins Dokument übernehmen' hinzu.",
        ["Forget"] = "Vergessen",
        ["Forget earlier conversions"] = "Frühere Umwandlungen vergessen",
