        ["Instances of which type below {0}?"] = "Instanzen welches Typs unterhalb von {0}?",
        ["Instances of {0}"] = "Instanzen von {0}",
        ["Instances, classes and libraries by the rules of the AutomationML/OPC Foundation working group (AML-UA-XSLT). OPC UA models imported by Annex A become AML classes in UA, not the UA nodes they were."] = "Instanzen, Klassen und Bibliotheken nach den Regeln der Arbeitsgruppe von AutomationML und OPC Foundation (AML-UA-XSLT). Nach Annex A importierte OPC-UA-Modelle werden zu AML-Klassen in UA, nicht wieder zu den UA-Knoten, aus denen sie stammen.",
