        ["Live: {0} = {1}  ·  {2} value(s) written."] = "Live: {0} = {1}  ·  {2} Wert(e) geschrieben.",
        ["Load kept selection"] = "Gemerkte Auswahl laden",
        ["Load the selection kept with what was taken from this server before, to take the same part again."] = "Die Auswahl laden, die sich das Plugin beim letzten Übernehmen von diesem Server gemerkt hat, um denselben Teil erneut zu übernehmen.",
