        ["Take into document"] = "Ins Dokument übernehmen",
        ["Take {0}"] = "{0} übernehmen",
        ["Take it with everything below"] = "Mit allem darunter übernehmen",
        ["Take it with its children"] = "Mit seinen Kindknoten übernehmen",
        ["Take only nodes of these namespaces, with what they hold."] = "Nur Knoten dieser Namespaces übernehmen, mit allem, was sie enthalten.",
        ["Take the node only"] = "Nur den Knoten übernehmen",
        ["Take the tutorial"] = "Tutorial durchgehen",
        ["Taking into the document failed: {0}"] = "Übernehmen ins Dokument fehlgeschlagen: {0}",
        ["Taking the NodeSet of {0} failed: {1}"] = "Übernehmen des NodeSets von {0} fehlgeschlagen: {1}",
        ["TechnicalResource to UA object"] = "TechnicalResource zu UA-Objekt",
        ["Terms: "] = "Begriffe: ",
        ["That is the round: model, serve, connect, take, follow. Click Stop serving to end the lesson."] = "Das war der ganze Ablauf: modellieren, bereitstellen, verbinden, übernehmen, verfolgen. Klicke auf 'Bereitstellung beenden', um die Lektion abzuschließen.",
        ["The address of a node on a server: its namespace and an identifier (a number, a string, a GUID or bytes). In the document the attribute NodeId (Annex A) holds it."] = "Die Adresse eines Knotens auf einem Server: sein Namespace und ein Bezeichner (eine Zahl, eine Zeichenkette, eine GUID oder Bytes). Im Dokument steht sie im Attribut NodeId (Annex A).",
        ["The clients the document server refused over the network, to trust, and those it trusts."] = "Clients, die der Dokumentserver im Netzwerk abgewiesen hat, und Clients, denen er vertraut. Hier gibst du einen abgewiesenen Client frei.",
        ["The clipboard is held by another program: {0}"] = "Die Zwischenablage wird von einem anderen Programm belegt: {0}",
        ["The Cloud Library needs a title, a description and a copyright."] = "Die Cloud Library braucht einen Titel, eine Beschreibung und einen Copyright-Vermerk.",
        ["The companion specifications the OPC Foundation publishes, with the models they require; no account needed."] = "Die Companion Specifications, die die OPC Foundation veröffentlicht, mit den Modellen, die sie benötigen; kein Konto nötig.",
        ["The document"] = "Das Dokument",
        ["The document changed while {0} was converted; import it again into the open one."] = "Das Dokument hat sich geändert, während {0} umgewandelt wurde; importiere es erneut in das geöffnete.",
        ["The document has no {0}. Process descriptions come from the FPB plugin (VDI 3682 library)."] = "Das Dokument enthält kein Element vom Typ {0}. Prozessbeschreibungen nach VDI 3682 (Formalisierte Prozessbeschreibung) legst du mit dem Plugin AMLFPB.js an (Bibliothek VDI 3682).",
        ["The document holds no OPC UA model imported by Annex A."] = "Das Dokument enthält kein nach Annex A importiertes OPC-UA-Modell.",
        ["Restart serving to show added or removed elements."] = "Starte die Bereitstellung neu, um hinzugefügte oder entfernte Elemente zu zeigen.",
        ["the document was closed"] = "das Dokument wurde geschlossen",
        ["The documentation URL is not a URL."] = "Die Dokumentations-URL ist keine URL.",
        ["The earlier state stays as it is."] = "Der bisherige Stand bleibt, wie er ist.",
        ["The element instantiates an abstract UA type."] = "Das Element ist eine Instanz eines abstrakten UA-Typs.",
        ["The element refers to a UA type that the document does not contain."] = "Das Element verweist auf einen UA-Typ, den das Dokument nicht enthält.",
        ["The element you choose gets the node's address as its NodeId attribute (OPC 10000-83 Annex A)."] = "Das Element, das du wählst, bekommt die Adresse des Knotens als Attribut NodeId (OPC 10000-83 Annex A).",
        ["The endpoint URL of a running server, such as opc.tcp://host:4840. With Secure ticked only secured endpoints are taken, the most secure the server offers: signed, and encrypted where offered. A server certificate this computer does not know is shown with its fingerprint before you trust it; trusted, exactly that one is kept. User and password are only sent over a secured connection; empty means anonymous. No server at hand? Practice plant starts the MPS 500 learning factory on this computer, with simulated values."] = "Die Endpunkt-URL eines laufenden Servers, etwa opc.tcp://host:4840. Ist 'Gesichert' angehakt, werden nur gesicherte Endpunkte verwendet, der sicherste, den der Server anbietet: signiert, und verschlüsselt, wo angeboten. Ein Serverzertifikat, das dieser Computer nicht kennt, wird mit seinem Fingerabdruck gezeigt, bevor du ihm vertraust; vertraust du ihm, wird genau dieses behalten. Benutzername und Passwort werden nur über eine gesicherte Verbindung gesendet; leer heißt anonym. Kein Server zur Hand? 'Übungsanlage' startet die Lernfabrik MPS 500 auf diesem Computer, mit simulierten Werten.",
        ["The identity of a server or client. Trusting a server's certificate says: this is the server I mean. The plugin keeps exactly the one you trusted."] = "Die Identität eines Servers oder Clients. Wer dem Zertifikat eines Servers vertraut, sagt damit: Das ist der Server, den ich meine. Das Plugin behält genau das Zertifikat, dem du vertraut hast.",
        ["The InstanceHierarchy that receives what is taken."] = "Die InstanceHierarchy, die das Übernommene aufnimmt.",
        ["The kind of link between two nodes, such as HasComponent, HasProperty, Organizes or HasTypeDefinition."] = "Die Art der Verbindung zwischen zwei Knoten, etwa HasComponent, HasProperty, Organizes oder HasTypeDefinition.",
        ["The lessons change the open document. Open a new, empty CAEX 3.0 document in the editor first (File, New), or save a practice document here and open it."] = "Die Lektionen ändern das geöffnete Dokument. Öffne zuerst im Editor ein neues, leeres CAEX-3.0-Dokument (File, New), oder speichere hier ein Übungsdokument und öffne es.",
        ["The libraries of {0} leave the document. No other namespace builds on it and no element uses its types. Ctrl+Z in the editor does not bring them back; importing the NodeSet again does."] = "Die Bibliotheken von {0} werden aus dem Dokument entfernt. Kein anderer Namespace baut darauf auf, und kein Element verwendet seine Typen. Strg+Z im Editor holt sie nicht zurück; ein erneuter Import des NodeSets schon.",
        ["The link is an attribute of the process element that names the OPC UA element."] = "Die Verknüpfung ist ein Attribut des Prozesselements, das das OPC-UA-Element nennt.",
        ["The list could not be read: {0}"] = "Die Liste konnte nicht gelesen werden: {0}",
        ["The log file could not be opened: {0}"] = "Die Protokolldatei konnte nicht geöffnet werden: {0}",
        ["The model holds {0} instance(s): {1} and {2} more. Where should they go?"] = "Das Modell enthält {0} Instanz(en): {1} und {2} weitere. Wohin sollen sie kommen?",
        ["The model holds {0} instance(s): {1}. Where should they go?"] = "Das Modell enthält {0} Instanz(en): {1}. Wohin sollen sie kommen?",
        ["The model in the modeler has changes that are neither applied to the document nor saved. Opening another model drops them."] = "Das Modell im Modeler hat Änderungen, die weder ins Dokument übernommen noch gespeichert sind. Wenn du ein anderes Modell öffnest, gehen sie verloren.",
        ["The model's NodeSet with a description, for others to find and download. The OPC Foundation reviews it before it is listed."] = "Das NodeSet des Modells mit einer Beschreibung, damit andere es finden und herunterladen können. Die OPC Foundation prüft es, bevor es gelistet wird.",
        ["The ModelCompiler could not compile {0}: {1}"] = "Der ModelCompiler konnte {0} nicht kompilieren: {1}",
        ["The modeler needs the NodeSet file of {0}: add the folder that holds it under Settings › NodeSet folders."] = "Der Modeler braucht die NodeSet-Datei von {0}: Füge den Ordner, der sie enthält, unter Einstellungen › NodeSet-Ordner hinzu.",
        ["The modeler stopped ({0}); reload it with the button above."] = "Der Modeler ist ausgefallen ({0}); lade ihn mit der Schaltfläche oben neu.",
        ["The NodeSet of {0} could not be read back from {1}."] = "Das NodeSet von {0} ließ sich nicht aus {1} zurücklesen.",
        ["The NodeSets the OPC Foundation publishes (github.com/OPCFoundation/UA-Nodeset), downloaded with the models they require and imported. No account needed."] = "Die NodeSets, die die OPC Foundation veröffentlicht (github.com/OPCFoundation/UA-Nodeset), werden mit den Modellen, die sie benötigen, heruntergeladen und importiert. Kein Konto nötig.",
        ["The NodeSets the OPC Foundation publishes, with the models they require, no account needed; or the UA Cloud Library."] = "Die NodeSets, die die OPC Foundation veröffentlicht, mit den Modellen, die sie benötigen, ohne Konto; oder die UA Cloud Library.",
        ["The OPC Foundation's online catalogue of information models (uacloudlibrary.opcfoundation.org). Searching it needs an account or an API key."] = "Der Online-Katalog der OPC Foundation für Informationsmodelle (uacloudlibrary.opcfoundation.org). Zum Durchsuchen brauchst du ein Konto oder einen API-Schlüssel.",
        ["The rules of the joint AutomationML and OPC Foundation working group for the other direction, from AML to OPC UA; the successor of OPC 30040. Export uses them."] = "Die Regeln der gemeinsamen Arbeitsgruppe von AutomationML und OPC Foundation für die Gegenrichtung, von AML nach OPC UA; der Nachfolger von OPC 30040. Der Export verwendet sie.",
        ["The search failed: {0}"] = "Die Suche ist fehlgeschlagen: {0}",
        ["The server at {0} presents a certificate this computer does not know. Trust it only if it is the server you mean: compare the fingerprint with the one its administrator gives you. Trusted, it is kept; a server that later shows another certificate is asked about again."] = "Der Server unter {0} zeigt ein Zertifikat, das dieser Computer nicht kennt. Vertraue ihm nur, wenn es der Server ist, den du meinst: Vergleiche den Fingerabdruck mit dem, den dir sein Administrator nennt. Vertraust du ihm, wird das Zertifikat behalten; zeigt der Server später ein anderes, wirst du erneut gefragt.",
        ["The server did not answer: {0} Disconnect and connect again if it restarted."] = "Der Server hat nicht geantwortet: {0} Trenne die Verbindung und verbinde dich neu, falls er neu gestartet wurde.",
        ["The server no longer has their nodes. Removed, they leave the document with everything below them; Ctrl+Z in the editor does not bring them back. Not removed, they stay, marked with NotOnServer."] = "Der Server hat ihre Knoten nicht mehr. Entfernst du sie, verschwinden sie mit allem darunter aus dem Dokument; Strg+Z im Editor holt sie nicht zurück. Entfernst du sie nicht, bleiben sie erhalten, markiert mit NotOnServer.",
        ["The Server object holds the server's own diagnostics and capabilities; it is hidden by default."] = "Das Server-Objekt enthält die eigenen Diagnosedaten und Fähigkeiten des Servers; standardmäßig ist es ausgeblendet.",
        ["The type has no Optional children."] = "Der Typ hat keine Optional-Kindelemente.",
        ["The types, DataTypes, ReferenceTypes, methods and objects that OPC 10000-83 Annex A put into the document, written back as UA nodes with their NodeIds. Not a standard: the inverse of Annex A. What Annex A leaves out (Documentation, type dictionaries, empty strings) does not come back."] = "Die Typen, DataTypes, ReferenceTypes, Methoden und Objekte, die OPC 10000-83 Annex A ins Dokument gebracht hat, als UA-Knoten mit ihren NodeIds zurückgeschrieben. Kein Standard, sondern die Umkehrung von Annex A. Was Annex A auslässt (Documentation, Type Dictionaries, leere Strings), kommt nicht zurück.",
        ["The URI that owns a set of nodes, such as http://opcfoundation.org/UA/DI/ for Device Integration. Every model has one, and every NodeId names it."] = "Die URI, der eine Menge von Knoten gehört, etwa http://opcfoundation.org/UA/DI/ für Device Integration. Jedes Modell hat eine, und jede NodeId nennt sie.",
        ["The Views the server defines: parts of its address space for a purpose."] = "Die Views, die der Server definiert: Teile seines Adressraums für einen bestimmten Zweck.",
        ["This document as a server"] = "Dieses Dokument als Server",
        ["This document uses CAEX {0}. The OPC UA libraries of OPC 10000-83 Annex A need CAEX 3.0 (AutomationML 2.10)."] = "Dieses Dokument verwendet CAEX {0}. Die OPC-UA-Bibliotheken nach OPC 10000-83 Annex A brauchen CAEX 3.0 (AutomationML 2.10).",
        ["This namespace belongs to the OPC Foundation. Publish only models you own."] = "Dieser Namespace gehört der OPC Foundation. Veröffentliche nur Modelle, die dir gehören.",
        ["Title"] = "Titel",
        ["to the network"] = "im Netzwerk",
        ["Trigger the editor's save command after a successful import."] = "Nach einem erfolgreichen Import den Speicherbefehl des Editors auslösen.",
        ["Trust this certificate"] = "Diesem Zertifikat vertrauen",
        ["Trust this server?"] = "Diesem Server vertrauen?",
        ["Trusted clients changed; they apply from a client's next connection."] = "Die vertrauenswürdigen Clients wurden geändert; die Änderung gilt ab der nächsten Verbindung eines Clients.",
        ["Try what Check finds: delete one of the Mandatory children of your instance in the editor's tree and click Check again. Add missing Mandatory children then puts it back. Click Next when done."] = "Probiere aus, was die Prüfung findet: Lösche im Baum des Editors eines der Mandatory-Kindelemente deiner Instanz und klicke auf 'Erneut prüfen'. 'Fehlende Mandatory-Kindelemente hinzufügen' stellt es dann wieder her. Klicke auf 'Weiter', wenn du fertig bist.",
        ["Tutorial"] = "Tutorial",
        ["Two children of {0} have the same name."] = "Zwei Kindelemente von {0} haben denselben Namen.",
        ["Type"] = "Typ",
        ["type  {0}"] = "Typ  {0}",
        ["Type name"] = "Typname",
        ["Type or instance to draw"] = "Typ oder Instanz zum Zeichnen",
        ["Types ({0})"] = "Typen ({0})",
        ["Types of the server"] = "Typen des Servers",
        ["Types of the server…"] = "Typen des Servers…",
        ["Types only"] = "Nur Typen",
        ["UA Cloud Library"] = "UA Cloud Library",
        ["UA Cloud Library…"] = "UA Cloud Library…",
        ["Update it"] = "Aktualisieren",
        ["Used by"] = "Verwendet von",
        ["User"] = "Benutzer",
        ["User name"] = "Benutzername",
        ["User name (empty for anonymous)"] = "Benutzername (leer für anonym)",
        ["Valid"] = "Gültig",
        ["Value"] = "Wert",
        ["Values and types are read again, new nodes are added. Elements whose node the server no longer has:"] = "Werte und Typen werden neu gelesen, neue Knoten kommen hinzu. Elemente, deren Knoten der Server nicht mehr hat:",
        ["VariableTypes"] = "VariableTypes",
        ["VDI 3682"] = "VDI 3682",
        ["VDI 3682 element"] = "VDI-3682-Element",
        ["VDI 3682 link set. Press Ctrl+S to save."] = "VDI-3682-Verknüpfung gesetzt. Drücke Strg+S, um zu speichern.",
        ["Version"] = "Version",
        ["Version {0}"] = "Version {0}",
        ["View"] = "View",
        ["Views ({0})"] = "Views ({0})",
        ["type '{0}' not found; import the NodeSet that defines it."] = "Typ '{0}' nicht gefunden; importiere das NodeSet, das ihn definiert.",
        ["waiting for the first value"] = "wartet auf den ersten Wert",
        ["Watch (view only)"] = "Beobachten (nur ansehen)",
        ["Watching failed: {0}"] = "Das Beobachten ist fehlgeschlagen: {0}",
        ["What is this? {0}"] = "Was ist das? {0}",
        ["What to do with the server"] = "Was du mit dem Server tun kannst",
        ["What to take"] = "Was übernommen wird",
        ["Where and how a server is reached: URL, security mode and security policy. A server usually offers several."] = "Wo und wie ein Server erreichbar ist: URL, Sicherheitsmodus und Sicherheitsrichtlinie (Security Mode, Security Policy). Ein Server bietet meist mehrere an.",
        ["Where NodeSets are searched and how an import treats the document."] = "Wo NodeSets gesucht werden und wie ein Import mit dem Dokument umgeht.",
        ["Where the server publishes a namespace's NodeSet, that file is taken; otherwise the NodeSet is rebuilt by browsing, without documentation links and without nodes no reference leads to."] = "Wo der Server das NodeSet eines Namespaces veröffentlicht, wird diese Datei genommen; sonst wird das NodeSet durch Browsen nachgebaut, ohne Dokumentationslinks und ohne Knoten, zu denen keine Referenz führt.",
        ["Write a CAEX 3.0 copy of this document (Aml.Engine's conversion) to a new file; open that file to import OPC UA libraries."] = "Eine CAEX-3.0-Kopie dieses Dokuments (Umwandlung durch die Aml.Engine) in eine neue Datei schreiben; öffne diese Datei, um OPC-UA-Bibliotheken zu importieren.",
        ["Write every change the server reports into the elements bound to it, until stopped."] = "Jede Änderung, die der Server meldet, in die an ihn gebundenen Elemente schreiben, bis du es stoppst.",
        ["Write the model as a ModelDesign file with its identifier file, the form the OPC Foundation's ModelCompiler reads."] = "Das Modell als ModelDesign-Datei mit ihrer Identifier-Datei schreiben, in der Form, die der ModelCompiler der OPC Foundation liest.",
        ["Writing the documentation"] = "Schreiben der Dokumentation",
        ["Writing the ModelDesign"] = "Schreiben des ModelDesigns",
        ["Zoom (Ctrl + mouse wheel)"] = "Zoom (Strg + Mausrad)",
        ["{0}   (not imported)"] = "{0}   (nicht importiert)",
        ["{0}  (at least one)"] = "{0}  (mindestens eines)",
        ["{0}  (node)"] = "{0}  (nur der Knoten)",
        ["{0}  (refused)"] = "{0}  (abgewiesen)",
        ["{0}  (with children)"] = "{0}  (mit Kindknoten)",
        ["{0}  (with everything below)"] = "{0}  (mit allem darunter)",
        ["{0}  in view {1}"] = "{0}  in View {1}",
        ["{0} (as declared)"] = "{0} (wie deklariert)",
        ["{0} (as declared, abstract)"] = "{0} (wie deklariert, abstrakt)",
        ["{0} answers again."] = "{0} antwortet wieder.",
        ["{0} cannot be read: {1}"] = "{0} kann nicht gelesen werden: {1}",
        ["{0} does not answer any more. Disconnect, and connect again once it is back."] = "{0} antwortet nicht mehr. Trenne die Verbindung und verbinde dich neu, sobald der Server wieder erreichbar ist.",
        ["{0} element(s) of the instance hierarchies use its types."] = "{0} Element(e) der InstanceHierarchies verwenden seine Typen.",
        ["{0} element(s)."] = "{0} Element(e).",
        ["{0} element(s); the node limit was reached. Raise 'at most' or check less."] = "{0} Element(e); die Höchstzahl der Knoten ist erreicht. Erhöhe 'höchstens' oder hake weniger an.",
        ["{0} error(s), {1} warning(s). Rules: "] = "{0} Fehler, {1} Warnung(en). Regeln: ",
        ["{0} failed: {1}"] = "{0} fehlgeschlagen: {1}",
        ["{0} file(s), {1:0.0} MB, taken from servers, the OPC Foundation and the Cloud Library. They are fetched again when an import needs them. Models applied from the modeler stay; the document is not changed."] = "{0} Datei(en), {1:0.0} MB, von Servern, der OPC Foundation und der Cloud Library abgerufen. Braucht ein Import sie, werden sie erneut abgerufen. Modelle, die aus dem Modeler übernommen wurden, bleiben; das Dokument wird nicht geändert.",
        ["{0} found below {1}. Each checked instance is taken with everything below it; unchecked ones are left out."] = "{0} unter {1} gefunden. Jede angehakte Instanz wird mit allem darunter übernommen; nicht angehakte werden ausgelassen.",
        ["{0} goes to uacloudlibrary.opcfoundation.org. Once the OPC Foundation has reviewed it, everyone can find and download it."] = "{0} wird an uacloudlibrary.opcfoundation.org gesendet. Sobald die OPC Foundation das Modell geprüft hat, können alle es finden und herunterladen.",
        ["{0} has no UA type in this document."] = "{0} hat in diesem Dokument keinen UA-Typ.",
        ["{0} instance(s) lack children their types now declare as Mandatory. They are added as a new instance would get them; nothing that exists changes. Ctrl+Z in the editor does not take them back."] = "Bei {0} Instanz(en) fehlen Kindelemente, die ihre Typen jetzt als Mandatory deklarieren. Ergänzt werden sie so, wie eine neue Instanz sie bekäme; nichts Vorhandenes ändert sich. Strg+Z im Editor nimmt das nicht zurück.",
        ["{0} is a ModelDesign, not a NodeSet. {1}"] = "{0} ist ein ModelDesign, kein NodeSet. {1}",
        ["{0} is not a NodeSet2 file."] = "{0} ist keine NodeSet2-Datei.",
        ["{0} is not an OPC UA NodeSet."] = "{0} ist kein OPC UA NodeSet.",
        ["{0} libraries"] = "{0} Bibliotheken",
        ["{0} linked to their planned element"] = "{0} mit ihrem geplanten Element verknüpft",
        ["{0} instance(s) with {1} element(s) taken into {2}"] = "{0} Instanz(en) mit {1} Element(en) in {2} übernommen",
        ["{0} Mandatory child(ren) are always created."] = "{0} Mandatory-Kindelement(e) werden immer angelegt.",
        ["{0} model(s). Choose one and download it."] = "{0} Modell(e). Wähle eines und lade es herunter.",
        ["{0} need at least one child (MandatoryPlaceholder). Create again to leave them empty for now."] = "{0} brauchen mindestens ein Kindelement (MandatoryPlaceholder). Klicke erneut auf 'Anlegen', um sie vorerst leer zu lassen.",
        ["{0} no longer on the server (kept, see log)"] = "{0} nicht mehr auf dem Server (behalten, siehe Protokoll)",
        ["{0} no longer on the server (marked with NotOnServer, not removed, see log)"] = "{0} nicht mehr auf dem Server (mit NotOnServer markiert, nicht entfernt, siehe Protokoll)",
        ["{0} no longer on the server (marked, see log)"] = "{0} nicht mehr auf dem Server (markiert, siehe Protokoll)",
        ["{0} no longer on the server (removed, see log)"] = "{0} nicht mehr auf dem Server (entfernt, siehe Protokoll)",
        ["{0} node(s), {1} added, {2} updated, {3} typed by an imported UA type"] = "{0} Knoten, {1} hinzugefügt, {2} aktualisiert, {3} mit einem importierten UA-Typ typisiert",
        ["{0} of {1} instance(s) of {2} below {3} checked."] = "{0} von {1} Instanz(en) von {2} unter {3} angehakt.",
        ["{0} of {1} model(s)."] = "{0} von {1} Modell(en).",
        ["{0} part(s) checked."] = "{0} Teil(e) angehakt.",
        ["{0} requires models that neither its folder nor the NodeSet folders hold. Fetch them from the OPC Foundation's published NodeSets (no account needed), add a folder that holds them, or search the UA Cloud Library; the import then tries again."] = "{0} benötigt Modelle, die weder in seinem Ordner noch in den NodeSet-Ordnern liegen. Rufe sie aus den veröffentlichten NodeSets der OPC Foundation ab (kein Konto nötig), füge einen Ordner hinzu, der sie enthält, oder durchsuche die UA Cloud Library; der Import versucht es dann erneut.",
        ["{0} The UA Cloud Library is an alternative."] = "{0} Die UA Cloud Library ist eine Alternative.",
        ["{0} to {1}"] = "{0} bis {1}",
        ["{0} to {1}  (expired)"] = "{0} bis {1}  (abgelaufen)",
        ["{0}: {1} nodes, truncated. Click a shape to select its element, double click to draw its type. Rules: M Mandatory, O Optional, MP and OP placeholders, E ExposesItsArray."] = "{0}: {1} Knoten, gekürzt. Klicke auf eine Form, um ihr Element auszuwählen; ein Doppelklick zeichnet ihren Typ. Regeln: M Mandatory, O Optional, MP und OP Platzhalter, E ExposesItsArray.",
        ["{0}: {1} nodes. Click a shape to select its element, double click to draw its type. Rules: M Mandatory, O Optional, MP and OP placeholders, E ExposesItsArray."] = "{0}: {1} Knoten. Klicke auf eine Form, um ihr Element auszuwählen; ein Doppelklick zeichnet ihren Typ. Regeln: M Mandatory, O Optional, MP und OP Platzhalter, E ExposesItsArray.",
        ["… and {0} more"] = "… und {0} weitere",
        ["… and {0} more (see log)"] = "… und {0} weitere (siehe Protokoll)",
    };
}
